import { memo } from 'react';
import { cn } from '@/lib/utils';

interface RichTipTextProps {
  text: string;
  className?: string;
  /** 主色（用于加粗高亮），不传则用默认 primary 文字色 */
  accentColor?: string;
}

/**
 * 技巧正文结构化渲染器
 * 支持格式：
 * - 【大白话：xxx】 开头 → 高亮引导语块
 * - ①②③④⑤⑥⑦⑧⑨⑩ 或 1. / 1、 / （1） 开头的句子 → 有序列表（每项单独一行）
 * - **xxx** → 加粗高亮
 * - 关键标签词自动加粗（核心：/ 重点：/ 公式：/ 方法：/ 步骤：/ 注意：/ 避坑：/ 底层逻辑：/ 目标：等）
 * - 自然段落 → 正常行间距
 */
function RichTipText({ text, className, accentColor }: RichTipTextProps) {
  if (!text) return null;

  // ===== 自动加粗关键标签词 =====
  const autoBoldKeywords = [
    '核心：', '核心要点：', '核心逻辑：', '底层逻辑：', '底层：',
    '重点：', '关键点：', '关键：', '核心原则：',
    '公式：', '计算公式：', '黄金公式：',
    '方法：', '方法论：', '实操方法：',
    '步骤：', '操作步骤：', '实操步骤：',
    '注意：', '注意事项：', '避坑：', '避坑点：',
    '目标：', '目的：', '适用：', '适用场景：',
    '痛点：', '问题：', '症状：',
    '判断：', '判断标准：', '结论：',
    '技巧：', '小技巧：', '进阶：', '进阶技巧：',
  ];
  let processed = text;
  for (const kw of autoBoldKeywords) {
    // 只对句首或空格后的关键词加粗（避免误伤中间文字）
    const regex = new RegExp(`(^|[。！？!?\n；; ])(${kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'g');
    processed = processed.replace(regex, (_, prefix, word) => `${prefix}**${word}**`);
  }

  // 预处理：先把 **加粗** 标记存下来，避免被分点逻辑干扰
  // 用占位符替换，最后再还原
  const boldSegments: string[] = [];
  processed = processed.replace(/\*\*(.+?)\*\*/g, (_, content) => {
    const idx = boldSegments.length;
    boldSegments.push(content);
    return `\u0000BOLD${idx}\u0000`;
  });

  // 拆分【大白话：...】前缀
  let intro: string | null = null;
  const introMatch = processed.match(/^【大白话[：: ](.+?)】/);
  if (introMatch) {
    intro = introMatch[1];
    processed = processed.slice(introMatch[0].length).trim();
  }

  // 按序号拆分列表项（①②③...⑩ 或 1. 2. 3. 或 1、2、3、或 （1）（2）（3）开头的完整句子）
  // 规则：序号在句首位置（字符串开头，或前一个字符是句末标点/空白/换行）才视为列表项分隔
  const circledNumbers = ['①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑨', '⑩'];
  const circledSet = new Set(circledNumbers);

  // 找到所有列表项的起始位置和序号值
  const itemStarts: { pos: number; num: number }[] = [];
  const len = processed.length;

  for (let i = 0; i < len; i++) {
    const ch = processed[i];

    // ①②③ 圈号格式
    if (circledSet.has(ch)) {
      if (i === 0) {
        itemStarts.push({ pos: i, num: circledNumbers.indexOf(ch) + 1 });
      } else {
        const prev = processed[i - 1];
        if (/[。！？!?\n\s；;]/.test(prev)) {
          itemStarts.push({ pos: i, num: circledNumbers.indexOf(ch) + 1 });
        }
      }
      continue;
    }

    // 1. / 2. / 10. 数字点格式（句首，前为空白/换行/句末标点）
    if (/\d/.test(ch)) {
      const prev = i === 0 ? '\n' : processed[i - 1];
      if (/[\n\s。！？!?；;]/.test(prev)) {
        // 向后找完整的数字
        let j = i;
        let numStr = '';
        while (j < len && /\d/.test(processed[j])) {
          numStr += processed[j];
          j++;
        }
        // 数字后面必须是 .  或 、 或 ）
        if (j < len && (processed[j] === '.' || processed[j] === '、')) {
          const num = parseInt(numStr, 10);
          if (num >= 1 && num <= 20) {
            itemStarts.push({ pos: i, num });
            i = j; // 跳过已处理字符
            continue;
          }
        }
        // （1） 格式
        if (prev === '（' && i > 0) {
          let j2 = i;
          let numStr2 = '';
          while (j2 < len && /\d/.test(processed[j2])) {
            numStr2 += processed[j2];
            j2++;
          }
          if (j2 < len && processed[j2] === '）') {
            const num = parseInt(numStr2, 10);
            if (num >= 1 && num <= 20) {
              // 左括号位置作为起点
              itemStarts.push({ pos: i - 1, num });
              i = j2;
              continue;
            }
          }
        }
      }
    }
  }

  // 根据起始位置切片
  const rawParts: string[] = [];
  if (itemStarts.length === 0) {
    rawParts.push(processed);
  } else {
    // 开头到第一个列表项之前的部分（如引导语残留）
    if (itemStarts[0].pos > 0) {
      const before = processed.slice(0, itemStarts[0].pos).trim();
      if (before) rawParts.push(before);
    }
    for (let i = 0; i < itemStarts.length; i++) {
      const start = itemStarts[i].pos;
      const end = i + 1 < itemStarts.length ? itemStarts[i + 1].pos : processed.length;
      rawParts.push(processed.slice(start, end).trim());
    }
  }

  // 判断是否是列表格式：大部分段落都以序号开头
  // 并从 itemStarts 取对应序号
  const listItems = rawParts.map((part, partIdx) => {
    const trimmed = part.trim();
    // 先匹配圈号
    for (let i = 0; i < circledNumbers.length; i++) {
      if (trimmed.startsWith(circledNumbers[i])) {
        return {
          type: 'list' as const,
          index: i + 1,
          content: trimmed.slice(circledNumbers[i].length).trim(),
        };
      }
    }
    // 匹配 数字. 或 数字、 格式
    const dotMatch = trimmed.match(/^(\d+)[.、]/);
    if (dotMatch) {
      const num = parseInt(dotMatch[1], 10);
      if (num >= 1 && num <= 20) {
        return {
          type: 'list' as const,
          index: num,
          content: trimmed.slice(dotMatch[0].length).trim(),
        };
      }
    }
    // 匹配 （数字） 格式
    const parenMatch = trimmed.match(/^（(\d+)）/);
    if (parenMatch) {
      const num = parseInt(parenMatch[1], 10);
      if (num >= 1 && num <= 20) {
        return {
          type: 'list' as const,
          index: num,
          content: trimmed.slice(parenMatch[0].length).trim(),
        };
      }
    }
    return { type: 'paragraph' as const, content: trimmed };
  });

  // 如果列表项 < 2 个，当作普通段落处理（不要强行做成列表）
  const listCount = listItems.filter(i => i.type === 'list').length;
  const isListFormat = listCount >= 2;

  // 渲染加粗占位符
  const renderBold = (str: string) => {
    const parts = str.split(/\u0000BOLD(\d+)\u0000/g);
    return parts.map((part, i) => {
      // 偶数下标是普通文本，奇数下标是加粗索引
      if (i % 2 === 1) {
        const idx = parseInt(part, 10);
        const content = boldSegments[idx] ?? '';
        return (
          <strong
            key={i}
            className="font-semibold"
            style={{ color: accentColor || undefined }}
          >
            {content}
          </strong>
        );
      }
      return <span key={i}>{part}</span>;
    });
  };

  // 长句自动折行：按句号/问号/感叹号分句，每句单独一行（移动端友好）
  const splitSentences = (str: string): string[] => {
    if (str.length < 60) return [str];
    // 按中文句号/问号/感叹号/分号拆分，保留分隔符
    const sentences: string[] = [];
    let buf = '';
    for (let i = 0; i < str.length; i++) {
      buf += str[i];
      if (/[。！？!?]/.test(str[i]) && i < str.length - 1) {
        sentences.push(buf.trim());
        buf = '';
      }
    }
    if (buf.trim()) sentences.push(buf.trim());
    // 如果只有 1 句，不拆
    if (sentences.length <= 1) return [str];
    return sentences;
  };

  return (
    <div className={cn('text-sm text-secondary-strong leading-relaxed', className)}>
      {/* 大白话引导语 */}
      {intro && (
        <div
          className="mb-2 rounded-lg px-3 py-2 text-xs font-medium"
          style={{
            backgroundColor: accentColor ? `${accentColor}10` : 'rgb(from var(--primary) r g b / 0.08)',
            color: accentColor || 'var(--primary)',
            borderLeft: `3px solid ${accentColor || 'var(--primary)'}`,
          }}
        >
          💡 {renderBold(intro)}
        </div>
      )}

       {/* 正文：列表或段落 */}
      {isListFormat ? (
        <ol className="space-y-2.5">
          {listItems.map((item, i) => (
            <li key={i} className="flex items-start gap-2">
              {item.type === 'list' ? (
                <>
                  <span
                    className="shrink-0 mt-0.5 size-5 rounded-full flex items-center justify-center text-[10px] font-bold text-white tabular-nums"
                    style={{ backgroundColor: accentColor || 'var(--primary)' }}
                  >
                    {item.index}
                  </span>
                  <div className="flex-1 min-w-0 leading-relaxed">
                    {splitSentences(item.content).map((sentence, si) => (
                      <div key={si} className={si > 0 ? 'mt-1' : ''}>
                        {renderBold(sentence)}
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <div className="flex-1 min-w-0">{renderBold(item.content)}</div>
              )}
            </li>
          ))}
        </ol>
      ) : (
        // 纯段落：按句号/问号/感叹号分句，每句一行（移动端友好）
        <div className="space-y-2">
          {listItems.map((item, i) => (
            <div key={i} className="space-y-1.5">
              {splitSentences(item.content).map((sentence, si) => (
                <p key={si} className="leading-relaxed">{renderBold(sentence)}</p>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default memo(RichTipText);
